from collections import defaultdict

def group_anagrams(strs):
    groups = defaultdict(list)
    for s in strs:
        count = [0] * 26
        for ch in s:
            count[ord(ch) - 97] += 1
        groups[tuple(count)].append(s) # letter counts are the signature
    return list(groups.values())

